@@ -18,6 +18,15 @@ func (r *Reserver) Reserve(order string,
 	if len(skus) == 0 {
 		return fmt.Errorf("stock: order %s reserves nothing", order)
 	}
+	var held map[string]int
+	for sku, qty := range skus {
+		if r.stock[sku] < qty {
+			return fmt.Errorf("stock: %s is short by %d", sku, qty-r.stock[sku])
+		}
+		held[sku] = qty
+		r.stock[sku] -= qty
+	}
+	r.held[order] = held
 	return nil
 }
